import urwid
import sys
import os

class LazyFileListWalker(urwid.ListWalker):
    def __init__(self, filename):
        self.filename = filename
        self.lines = []
        self.loaded = False
        self.focus = 0
        self.load_file()

    def load_file(self):
        if not self.loaded:
            if os.path.exists(self.filename):
                with open(self.filename, 'r', encoding='utf-8') as f:
                    self.lines = [line.rstrip('\n') for line in f]
            else:
                self.lines = [""]
            if not self.lines:
                self.lines = [""]
            self.loaded = True

    def get_focus(self):
        return self._get_at_pos(self.focus)

    def set_focus(self, focus):
        self.focus = focus
        self._modified()

    def get_next(self, pos):
        return self._get_at_pos(pos + 1)

    def get_prev(self, pos):
        return self._get_at_pos(pos - 1)

    def _get_at_pos(self, pos):
        if pos < 0 or pos >= len(self.lines):
            return None, None
        return LineEdit(self, pos), pos

    def insert_line(self, pos, text=""):
        self.lines.insert(pos, text)
        self._modified()

    def remove_line(self, pos):
        if len(self.lines) > 1:
            del self.lines[pos]
            if self.focus >= len(self.lines):
                self.focus = len(self.lines) - 1
            self._modified()

    def set_line(self, pos, text):
        self.lines[pos] = text
        self._modified()

    def get_line(self, pos):
        return self.lines[pos]

    def combine_with_next(self, pos):
        if pos < len(self.lines) - 1:
            self.lines[pos] += self.lines[pos + 1]
            self.remove_line(pos + 1)
            self._modified()

    def split_line(self, pos, at):
        line = self.lines[pos]
        self.lines[pos] = line[:at]
        self.insert_line(pos + 1, line[at:])
        self._modified()

    def save(self):
        with open(self.filename, 'w', encoding='utf-8') as f:
            for line in self.lines:
                f.write(line + '\n')

class LineEdit(urwid.Edit):
    def __init__(self, walker, pos):
        super().__init__("", walker.get_line(pos))
        self.walker = walker
        self.pos = pos
        self.set_edit_text(walker.get_line(pos))
        self.set_edit_pos(len(self.edit_text))

    def keypress(self, size, key):
        if key == 'left':
            if self.edit_pos > 0:
                return super().keypress(size, key)
            elif self.pos > 0:
                self.walker.set_focus(self.pos - 1)
                prev_line = self.walker.get_line(self.pos - 1)
                self._emit('set_edit_pos', len(prev_line))
                return None
            else:
                return None
        elif key == 'right':
            if self.edit_pos < len(self.edit_text):
                return super().keypress(size, key)
            elif self.pos < len(self.walker.lines) - 1:
                self.walker.set_focus(self.pos + 1)
                self._emit('set_edit_pos', 0)
                return None
            else:
                return None
        elif key == 'up':
            if self.pos > 0:
                self.walker.set_focus(self.pos - 1)
                prev_line = self.walker.get_line(self.pos - 1)
                self._emit('set_edit_pos', min(self.edit_pos, len(prev_line)))
                return None
            else:
                return None
        elif key == 'down':
            if self.pos < len(self.walker.lines) - 1:
                self.walker.set_focus(self.pos + 1)
                next_line = self.walker.get_line(self.pos + 1)
                self._emit('set_edit_pos', min(self.edit_pos, len(next_line)))
                return None
            else:
                return None
        elif key == 'backspace':
            if self.edit_pos > 0:
                return super().keypress(size, key)
            elif self.pos > 0:
                prev_line = self.walker.get_line(self.pos - 1)
                curr_line = self.edit_text
                new_pos = len(prev_line)
                self.walker.combine_with_next(self.pos - 1)
                self.walker.set_focus(self.pos - 1)
                self.walker._modified()
                self._emit('set_edit_pos', new_pos)
                return None
            else:
                return None
        elif key == 'delete':
            if self.edit_pos < len(self.edit_text):
                return super().keypress(size, key)
            elif self.pos < len(self.walker.lines) - 1:
                self.walker.combine_with_next(self.pos)
                self.walker.set_focus(self.pos)
                self.walker._modified()
                self._emit('set_edit_pos', len(self.edit_text))
                return None
            else:
                return None
        elif key == 'enter':
            left = self.edit_text[:self.edit_pos]
            right = self.edit_text[self.edit_pos:]
            self.walker.set_line(self.pos, left)
            self.walker.insert_line(self.pos + 1, right)
            self.walker.set_focus(self.pos + 1)
            self.walker._modified()
            self._emit('set_edit_pos', 0)
            return None
        else:
            res = super().keypress(size, key)
            self.walker.set_line(self.pos, self.edit_text)
            return res

    def selectable(self):
        return True

    def mouse_event(self, size, event, button, col, row, focus):
        return False

    def set_edit_pos(self, pos):
        self.set_edit_pos(pos)

class TextEditor:
    def __init__(self, filename):
        self.walker = LazyFileListWalker(filename)
        self.listbox = urwid.ListBox(self.walker)
        self.footer = urwid.Text(
            u"Ctrl+S: Save | Ctrl+Q: Quit | Arrows: Move | Enter: New Line | Backspace/Delete: Join Lines"
        )
        self.frame = urwid.Frame(self.listbox, footer=self.footer)
        self.loop = urwid.MainLoop(
            self.frame,
            unhandled_input=self.unhandled_input,
            handle_mouse=False
        )
        urwid.connect_signal(self.walker, 'modified', self.on_modified)

    def on_modified(self):
        self.loop.draw_screen()

    def unhandled_input(self, key):
        if key in ('ctrl s',):
            self.walker.save()
            self.footer.set_text(u"Saved.")
        elif key in ('ctrl q',):
            raise urwid.ExitMainLoop()
        else:
            self.footer.set_text(
                u"Ctrl+S: Save | Ctrl+Q: Quit | Arrows: Move | Enter: New Line | Backspace/Delete: Join Lines"
            )

    def run(self):
        self.loop.run()

def main(filename):
    editor = TextEditor(filename)
    editor.run()

if __name__ == "__main__":
    if len(sys.argv) < 2:
        print("Usage: python text_editor.py <filename>")
        sys.exit(1)
    main(sys.argv[1])
